    margin-top: -24px; /* slight upward shift for golden ratio vertical center */
  }

  /* Floating "Agent" */
  .floating-agent {
    font-family: 'Inter', sans-serif;
    font-weight: 200;
    font-size: 128px;
    letter-spacing: -4px;
    color: #1A1A18;
    line-height: 1;
    margin-bottom: 16px;
    position: relative;
  }

  .floating-agent span {
    position: relative;
    display: inline-block;
  }

  /* Slight weight shift on first letter for visual interest */
  .floating-agent .accent-letter {
    font-weight: 300;
    color: #2A2A28;
  }

  /* Gold underline accent */
  .gold-line {
    width: 48px;
    height: 1px;
    background: #D4A574;
    margin: 0 auto 32px;
    opacity: 0.7;
  }

  /* Subtitle — label tier: smallest text, widest spacing */
  .subtitle {
    font-family: 'Inter', sans-serif;
    font-weight: 400;
    font-size: 10px;
    letter-spacing: 6px;
    text-transform: uppercase;
    color: #B0ACA4;
    margin-bottom: 24px;
  }

  /* Description line — body tier */
  .desc {
    font-family: 'Inter', sans-serif;
    font-weight: 300;
    font-size: 13px;
    color: #A8A4A0;
    letter-spacing: 0.3px;
    line-height: 2;
    max-width: 400px;
    margin: 0 auto;
  }

  /* Minimal agent indicators — 8 thin vertical lines */
  .agent-indicators {
    position: absolute;
    bottom: 48px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    gap: 16px;
    align-items: flex-end;
    z-index: 2;
  }

  .indicator {
    width: 1px;
    background: #D8D4CE;
    border-radius: 0.5px;
  }

  .indicator.gold {
    background: #D4A574;
    width: 1.5px;
    opacity: 0.8;
  }

  /* Corner marks */
  .corner-mark {
    position: absolute;
    z-index: 2;
  }

  .corner-mark svg {
    display: block;
  }

  .corner-tl { top: 48px; left: 48px; }
  .corner-br { bottom: 48px; right: 48px; transform: rotate(180deg); }

  /* Side text */
  .side-label {
    position: absolute;
    font-family: 'Inter', sans-serif;
    font-weight: 400;
    font-size: 8px;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: #CBC7C0;
    z-index: 2;
  }

  .side-left {
    left: 48px;
    top: 50%;
    transform: translateY(-50%) rotate(-90deg);
    transform-origin: center center;
  }

  .side-right {
    right: 48px;
    top: 50%;
    transform: translateY(-50%) rotate(90deg);
    transform-origin: center center;
  }

  /* Removed shadow-card — Build purity demands uninterrupted whitespace */

  /* Number 8 whisper */
  .number-whisper {
    position: absolute;
    top: 48px;
    right: 96px;
    font-family: 'Inter', sans-serif;
    font-weight: 200;
    font-size: 24px;
    color: #D4A574;
    opacity: 0.35;
    z-index: 2;
  }
</style>
</head>
<body>

