}
* { box-sizing: border-box; }

.stage {
  position: fixed;
  top: 50%; left: 50%;
  width: 1920px; height: 1080px;
  transform-origin: center center;
  background: var(--bg);
  overflow: hidden;
}

/* Subtle film grain overlay, 2% */
.stage::after {
  content: '';
  position: absolute; inset: 0;
  pointer-events: none;
  opacity: 0.025;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='300' height='300'><filter id='n'><feTurbulence baseFrequency='0.9' numOctaves='2'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  mix-blend-mode: overlay;
  z-index: 200;
}

/* Watermark */
.watermark-tl {
  position: absolute;
  top: 40px; left: 56px;
  font-family: var(--mono);
  font-size: 14px;
  letter-spacing: 0.2em;
  color: rgba(255,255,255,0.16);
  z-index: 50;
  text-transform: none;
  font-weight: 500;
}
.watermark-br {
  position: absolute;
  bottom: 32px; right: 48px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.24em;
  color: rgba(255,255,255,0.22);
  z-index: 100;
