}
.watermark-br.visible { opacity: 1; }

/* Scene container */
.scene {
  position: absolute; inset: 0;
  opacity: 0;
  visibility: hidden;
  will-change: opacity;
}
.scene.visible { visibility: visible; }

/* ============ Split layout ============ */
.split {
  position: absolute; inset: 0;
}
.split-top {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 48%;
  display: flex;
