}
.morph-label .val { color: var(--accent); font-variant-numeric: tabular-nums; }
.morph-arrow {
  font-family: var(--mono);
  font-size: 28px;
  color: var(--muted);
  letter-spacing: 0.2em;
}

/* viz 3: Easing — curves */
.viz-curves {
  position: relative;
  width: 720px; height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.curves-svg {
