  }

  /* ============ Single Fix row (Concept Card lean) ============ */
  .fix-lane {
    position: absolute;
    left: 150px;
    bottom: 120px;
    width: 1620px;
    opacity: 0;
    will-change: opacity, transform;
  }
  .fix-head {
    display: flex;
    align-items: baseline;
