    border-radius: 50%;
    top: 50%;
    left: 30%;
    transform: translate(-50%, -50%);
  }

  .gui-glyph.folder {
    /* Window frame w/ file list */
    width: 420px; height: 260px;
    background: rgba(255,255,255,0.02);
    border: 1px solid var(--hairline);
    border-radius: 10px;
    overflow: hidden;
  }
  .gui-glyph.folder .head {
