  }
  .prompt { color: var(--accent); margin-right: 12px; }
  .typed { white-space: pre; }
  .cursor {
    display: inline-block;
    width: 12px; height: 28px;
    background: var(--accent);
    vertical-align: -5px;
    margin-left: 3px;
  }

  /* Gallery (v6 structure, dark theme) */
  .gallery-viewport {
    position: absolute;
    inset: 0;
    overflow: hidden;
    perspective: 2400px;
    perspective-origin: 50% 45%;
  }
  .gallery-canvas {
