  }
  .gallery-card.depth-far {
    box-shadow:
      0 14px 40px -16px rgba(0, 0, 0, 0.4),
      0 4px 12px -4px rgba(0, 0, 0, 0.25);
  }
  .gallery-card img {
    width: 100%; height: 100%;
    object-fit: cover;
    display: block;
    border-radius: 9px;
  }

  /* Overlay statements (on top of gallery) */
  .over-statement {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: none;
    z-index: 50;
