  }
  .over-statement .text .accent { color: var(--accent); }

  /* ============ Act 3 ============ */
  .act3 {
    flex-direction: column;
    gap: 0;
  }
  .statement-big {
    font-family: var(--sans);
    font-size: 160px;
    font-weight: 100;
