    line-height: 1;
    will-change: font-variation-settings, opacity, transform;
  }
  .brand-wordmark .accent { color: var(--accent); font-weight: inherit; }

  .farewell-quote {
    margin-top: 44px;
    font-family: var(--serif-en);
    font-style: italic;
    font-weight: 300;
    font-size: 36px;
    color: var(--accent);
