    letter-spacing: 0.24em;
    text-align: center;
  }

  .brand-url {
    margin-top: 48px;
    font-size: 14px;
    color: var(--muted);
    font-family: var(--mono);
    letter-spacing: 0.16em;
    text-align: center;
  }

  /* Watermark (subtle, always on during Act 2/3) */
  .watermark {
    position: absolute;
    bottom: 28px;
    right: 36px;
    font-family: var(--mono);
    font-size: 10px;
    letter-spacing: 0.24em;
    text-transform: uppercase;
    color: rgba(255,255,255,0.22);
    z-index: 100;
    opacity: 0;
    transition: opacity 0.6s;
