  .cd-traffic .d.r { background: #E8A5A0; }
  .cd-traffic .d.y { background: #E8D0A0; }
  .cd-traffic .d.g { background: #A5D0B0; }
  .cd-urlbar {
    flex: 1;
    max-width: 520px;
    margin: 0 auto;
    height: 28px;
    background: #F9F7F2;
    border: 1px solid var(--cd-hair);
