    display: flex; align-items: center; justify-content: center;
    font-family: var(--sans);
    font-size: 13px;
    color: var(--cd-dim);
    letter-spacing: 0;
  }
  .cd-urlbar .lock {
    width: 10px; height: 10px;
    margin-right: 8px;
    border: 1.5px solid var(--cd-dim);
    border-radius: 2px;
    position: relative;
  }
  .cd-urlbar .lock::before {
