  const COMMAND = '/huashu-design 做一份发布会PPT';

  // ---------- Gallery transforms ----------
  const GALLERY_TILT = 'perspective(2400px) rotateX(14deg) rotateY(-10deg) rotateZ(-2deg)';
  const GALLERY_SCALE = 0.94;
