<style>
  :root {
    --bg: #000000;
    --ink: #FFFFFF;
    --ink-80: rgba(255,255,255,0.82);
    --ink-60: rgba(255,255,255,0.58);
    --muted: rgba(255,255,255,0.40);
    --dim: rgba(255,255,255,0.18);
    --hairline: rgba(255,255,255,0.12);
    --accent: #D97757;
    --accent-deep: #B85D3D;
    --cd-bg: #F5F4F0;
    --cd-panel: #FFFFFF;
    --cd-ink: #1A1918;

    --serif-zh: "Noto Serif SC", "Songti SC", serif;
    --serif-en: "Source Serif 4", "Tiempos Headline", Georgia, serif;
    --sans: "Inter", -apple-system, "PingFang SC", "HarmonyOS Sans SC", system-ui, sans-serif;
    --mono: "JetBrains Mono", "SF Mono", ui-monospace, monospace;
  }
  html, body {
    margin: 0; padding: 0;
    background: #000;
    overflow: hidden;
    font-family: var(--sans);
    color: var(--ink);
    -webkit-font-smoothing: antialiased;
  }
  * { box-sizing: border-box; }

  .stage {
    position: fixed;
    top: 50%; left: 50%;
    width: 1920px; height: 1080px;
    transform-origin: center center;
    background: var(--bg);
    overflow: hidden;
  }

  /* Film grain texture (very subtle) */
  .stage::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='300' height='300'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='0.5'/></svg>");
    opacity: 0.02;
    pointer-events: none;
    z-index: 100;
  }

  /* Chrome · watermark */
  .mark {
    position: absolute;
    top: 48px; left: 64px;
    font-family: var(--mono);
    font-size: 13px;
    letter-spacing: 0.2em;
    color: rgba(255,255,255,1);
    opacity: 0.16;
    pointer-events: none;
    z-index: 50;
  }
  .mark-right {
    position: absolute;
    top: 48px; right: 64px;
    font-family: var(--mono);
    font-size: 13px;
    letter-spacing: 0.2em;
    color: rgba(255,255,255,1);
    opacity: 0.16;
    pointer-events: none;
    z-index: 50;
  }

  /* ====== Title (centered, small, top) ====== */
  .title-line {
    position: absolute;
    top: 128px;
    left: 50%;
    transform: translateX(-50%);
    font-family: var(--mono);
    font-size: 14px;
    letter-spacing: 0.28em;
    color: var(--muted);
    text-transform: uppercase;
    opacity: 0;
    will-change: opacity, transform;
  }

  /* ====== Chain · 5 cards connected by a line ====== */
  .chain {
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    width: 1680px;
    height: 360px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 80px;
  }

  /* The connecting line behind the cards */
  .chain-line {
    position: absolute;
    top: 50%;
    left: 140px;
    right: 140px;
    height: 1px;
    background: linear-gradient(90deg,
      transparent 0%,
      rgba(217,119,87,0.0) 2%,
