  }
  .tty-body .prompt { color: var(--accent); margin-right: 10px; }
  .tty-body .dim { color: var(--muted); }

  /* The long running progress bar (simulated "3-hour render") */
  .progress-row {
    margin-top: 14px;
    display: flex;
    align-items: center;
    gap: 14px;
    font-family: var(--mono);
