    margin-bottom: 22px;
  }
  .fg-card .feature {
    font-family: var(--sans);
    font-size: 13px;
    font-weight: 300;
    letter-spacing: 0.03em;
    color: var(--muted);
    line-height: 1.6;
    padding-top: 18px;
    border-top: 1px solid var(--hairline);
    text-transform: uppercase;
  }
  .fg-card .thumb-wrap {
    margin-top: 14px;
    height: 0;
    overflow: hidden;
    border-radius: 10px;
    background: #0a0a0a;
    border: 1px solid var(--hairline);
    opacity: 0;
    will-change: opacity, height;
  }
  .fg-card .thumb-wrap img {
    width: 100%;
    display: block;
  }

  /* Brand reveal */
  .brand-panel {
    position: absolute;
    inset: 0;
