  .brand-mark .dot { color: var(--accent); font-style: normal; padding: 0 6px; }
  .brand-mark .accent { color: var(--accent); font-style: italic; }
  .brand-underline {
    margin-top: 34px;
    height: 2px;
    width: 0;
    background: var(--accent);
